题型:RCE
漏洞原因:eval($code);
 &lt;?php
error_reporting(0);
if(!isset($_GET[&#039;code&#039;])){
    highlight_file(__FILE__);
}else{
    $code = $_GET[&#039;code&#039;];
    if(preg_match(&quot;/[A-Za-z0-9_$@]+/&quot;,$code)){
        die(&#039;fighting!&#039;); 
    }
