        heroImg[i] = nImg(imgName[8][i]);
    }

    function nImg(src) {
        var img = new Image();
        img.src = &#039;img/&#039; + src;
        img.onload = imgLoad;
        return img;
    }
    // 绘制游戏加载进度画面
    function imgLoad() {
        progress += 3;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        var text = progress + &#039;%&#039;;
        var tw = ctx.measureText(text).width;
        ctx.font = &#039;60px arial&#039;;
        ctx.fillStyle = &#039;red&#039;;
        ctx.lineWidth = &#039;0&#039;;
        ctx.strokeStyle = &#039;#888&#039;;
        //ctx.strokeText(text,(width-tw)/2,height/2);
        ctx.fillText(text, (width - tw) / 2, height / 2);
        if (progress &gt;= 100) {
            start();
        }
    }
}
download();

/*********开始游戏**************/
