function loading() {
    this.index = 0;

    function loading() {
        this.index % 1 == 0 &amp;&amp; ctx.drawImage(gameLoad[index], 0, canvas.height - gameLoad[0].height);
        this.index += 0.5;
        if (this.index &gt; 3) {
            curPhase = PHASE_PLAY;
